script:
frappe.ui.form.on('Rumba Unit', {
  jumlah_ruang_kelas(frm) {
    const jumlah = cint(frm.doc.jumlah_ruang_kelas || 0);
    frm.set_value('kapasitas_max_sesi_belajar_minggu', jumlah * 40);
  }
});

frappe.ui.form.on('Rumba Unit', {
  refresh(frm) {
    hitung_kapasitas(frm);
  },
  kapasitas_max_sesi_belajar_minggu(frm) {
    hitung_kapasitas(frm);
  }
});

function hitung_kapasitas(frm) {
  const sesi = flt(frm.doc.kapasitas_max_sesi_belajar_minggu || 0);
  const hasil = sesi * 3; // sama dengan (sesi / 2) * 6
  frm.set_value('kapasitas_max_murid', hasil);
}

frappe.listview_settings['Rumba Unit'] = {
  add_fields: ['status_unit', 'kepemilikan'],

  // Warna badge per kolom
  formatters: {
    status_unit(value) {
      const map = {
        'Rintisan': 'blue',
        'Aktif': 'green',
        'Pindah': 'red',
        'Tutup': 'gray'
      };
      return make_pill(value, map);
    },

    kepemilikan(value) {
      const map = {
        'Crowdfunding': 'orange',
        'Franchise': 'blue',
        'YRKI': 'green'
      };
      return make_pill(value, map);
    }
  },

  // Opsional: indikator utama baris ikut warna status_unit
  get_indicator(doc) {
    const map = {
      'Rintisan': 'blue',
      'Aktif': 'green',
      'Pindah': 'red',
      'Tutup': 'gray'
    };
    const s = doc.status_unit || 'Tutup';
    return [__(s), map[s] || 'gray', `status_unit,=,${s}`];
  }
};

function make_pill(value, color_map) {
  const val = value || '';
  const color = color_map[val] || 'gray';
  return `<span class="indicator-pill ${color}">${frappe.utils.escape_html(__(val))}</span>`;
}

frappe.ui.form.on("Rumba Program Belajar", {
  kode_program_belajar(frm) {
    const v = (frm.doc.kode_program_belajar || "").toUpperCase().trim();
    if (v !== frm.doc.kode_program_belajar) {
      frm.set_value("kode_program_belajar", v);
    }
  }
});

frappe.ui.form.on('Rumba Tahun Ajaran', {
	tanggal_mulai(frm) {
		if (!frm.doc.tanggal_mulai) {
			frm.set_value('tanggal_selesai', null);
			return;
		}

		const start = frappe.datetime.str_to_obj(frm.doc.tanggal_mulai);
		const endDate = new Date(start.getFullYear() + 1, 5, 30); // 30 Juni tahun berikutnya
		frm.set_value('tanggal_selesai', frappe.datetime.obj_to_str(endDate));
	}
});

frappe.listview_settings['Rumba Tahun Ajaran'] = {
  add_fields: ['status'],

  formatters: {
    status(value) {
      const map = {
        'Aktif': 'green',
        'Arsip': 'red'
      };
      return make_pill(value, map);
    }
  },

  // Indikator utama baris mengikuti warna status
  get_indicator(doc) {
    const map = {
      'Aktif': 'green',
      'Arsip': 'red'
    };
    const s = doc.status || 'Arsip';
    return [__(s), map[s] || 'gray', `status,=,${s}`];
  }
};

function make_pill(value, color_map) {
  const val = value || '';
  const color = color_map[val] || 'gray';
  return `<span class="indicator-pill ${color}">${frappe.utils.escape_html(__(val))}</span>`;
}

frappe.ui.form.on('Semester', {
	refresh(frm) {
		generate_semester_fields(frm);
	},
	kode_tahun_ajaran(frm) {
		generate_semester_fields(frm);
	},
	periode_semester(frm) {
		generate_semester_fields(frm);
	}
});

function extract_years(text) {
	const s = String(text || '');
	const m = s.match(/(\d{4})\D+(\d{4})/); // contoh: 2026-2027
	if (!m) return null;
	return { y1: m[1], y2: m[2] };
}

function generate_semester_fields(frm) {
	const taLink = frm.doc.kode_tahun_ajaran;
	const periode = (frm.doc.periode_semester || '').trim();

	if (!taLink || !periode) {
		frm.set_value('kode_semester', '');
		frm.set_value('nama_semester', '');
		frm.set_value('tanggal_mulai_semester', null);
		frm.set_value('tanggal_akhir_semester', null);
		return;
	}

	frappe.db.get_value(
		'Rumba Tahun Ajaran',
		taLink,
		['kode_tahun_ajaran', 'nama_tahun_ajaran']
	).then(r => {
		const row = (r && r.message) || {};
		const kodeTA = row.kode_tahun_ajaran || taLink; // contoh: 2627
		const taText = row.nama_tahun_ajaran || row.kode_tahun_ajaran || taLink; // contoh: 2026-2027
		const years = extract_years(taText);

		let kodePeriode = '';
		let angkaPeriode = '';
		let startDate = null;
		let endDate = null;

		if (periode.startsWith('S1')) {
			kodePeriode = 'S1';
			angkaPeriode = '1';
			// Jul-Des tahun pertama
			if (years) {
				startDate = `${years.y1}-07-01`;
				endDate = `${years.y1}-12-31`;
			}
		} else if (periode.startsWith('S2')) {
			kodePeriode = 'S2';
			angkaPeriode = '2';
			// Jan-Jun tahun kedua
			if (years) {
				startDate = `${years.y2}-01-01`;
				endDate = `${years.y2}-06-30`;
			}
		} else {
			frm.set_value('kode_semester', '');
			frm.set_value('nama_semester', '');
			frm.set_value('tanggal_mulai_semester', null);
			frm.set_value('tanggal_akhir_semester', null);
			return;
		}

		frm.set_value('kode_semester', `${kodeTA}-${kodePeriode}`);
		frm.set_value('nama_semester', `${kodeTA}-SMTR-${angkaPeriode}`);
		frm.set_value('tanggal_mulai_semester', startDate);
		frm.set_value('tanggal_akhir_semester', endDate);
	});
}

frappe.ui.form.on("Rumba Pendaftaran", {
	setup(frm) {
		frm.set_query("nama_unit", () => {
			if (!frm.doc.nama_kota) {
				return {
					filters: {
						name: ["is", "not set"]
					}
				};
			}

			return {
				filters: {
					kode_kota: frm.doc.nama_kota
				}
			};
		});
	},

	nama_kota(frm) {
		frm.set_value("nama_unit", "");
		frm.set_value("kode_unit", "");
	}
});

frappe.ui.form.on("Rumba Pendaftaran", {
  refresh(frm) {
    if (
      frm.doc.docstatus === 0 &&
      frm.doc.status_pendaftaran === "Disetujui" &&
      !frm.doc.murid_rumba
    ) {
      frm.add_custom_button(__("Buat Murid"), () => {
        frm.trigger("buat_murid");
      });
    }
  },

  buat_murid(frm) {
    frappe.confirm(
      __("Buat data murid dari pendaftaran ini?"),
      () => {
        frappe.call({
          method: "frappe.client.insert",
          args: {
            doc: {
              doctype: "Rumba Murid",

              // Nomor Induk Murid memakai ID/naming Rumba Pendaftaran
              nomor_induk_murid: frm.doc.name,

              pendaftaran: frm.doc.name,
              nama_lengkap: frm.doc.nama_lengkap,
              nama_panggilan: frm.doc.nama_panggilan,
              tanggal_lahir: frm.doc.tanggal_lahir,
              jenis_kelamin: frm.doc.jenis_kelamin,
              tempat_lahir: frm.doc.tempat_lahir,

              nama_unit: frm.doc.nama_unit,
              kode_unit: frm.doc.kode_unit,
              tahun_ajaran: frm.doc.tahun_ajaran,
              program_belajar: frm.doc.program_belajar,
              jenis_kelas: frm.doc.jenis_kelas,

              nama_orang_tua_wali: frm.doc.nama_orang_tua_wali,
              hubungan_dengan_anak: frm.doc.hubungan_dengan_anak,
              nomor_handphone: frm.doc.nomor_handphone,
              alamat: frm.doc.alamat,

              senin: frm.doc.senin,
              selasa: frm.doc.selasa,
              rabu: frm.doc.rabu,
              kamis: frm.doc.kamis,
              jumat: frm.doc.jumat,
              sabtu: frm.doc.sabtu,
              jam_belajar: frm.doc.jam_belajar
            }
          },
          freeze: true,
          freeze_message: __("Membuat data murid..."),
          callback(r) {
            if (!r.exc && r.message) {
              frm.set_value("murid_rumba", r.message.name);
              frm.save().then(() => {
                frappe.msgprint({
                  title: __("Murid Dibuat"),
                  message: __("Data murid {0} berhasil dibuat.", [r.message.name]),
                  indicator: "green"
                });
                frm.reload_doc();
              });
            }
          }
        });
      }
    );
  }
});

frappe.listview_settings["Rumba Murid"] = {
  add_fields: ["status_murid"],

  get_indicator(doc) {
    const colors = {
      "Aktif": "green",
      "Cuti": "gray",
      "Lulus": "blue",
      "Berhenti": "red"
    };

    return [
      __(doc.status_murid || "Belum Diisi"),
      colors[doc.status_murid] || "gray",
      `status_murid,=,${doc.status_murid || ""}`
    ];
  },

  formatters: {
    status_murid(value) {
      const colors = {
        "Aktif": "green",
        "Cuti": "gray",
        "Lulus": "blue",
        "Berhenti": "red"
      };

      const color = colors[value] || "gray";

      return `<span class="indicator-pill ${color}">
        <span class="indicator-dot"></span>
        ${frappe.utils.escape_html(value || "")}
      </span>`;
    }
  }
};

frappe.ui.form.on("Rumba Pendaftaran", {
  refresh(frm) {
    if (!frm.doc.customer_orang_tua && frm.doc.nama_orang_tua_wali) {
      frm.add_custom_button(__("Buat Customer"), () => {
        frm.trigger("buat_customer_orang_tua");
      });
    }

    if (frm.doc.customer_orang_tua) {
      frm.add_custom_button(__("Buka Customer"), () => {
        frappe.set_route("Form", "Customer", frm.doc.customer_orang_tua);
      });
    }
  },

  buat_customer_orang_tua(frm) {
    if (!frm.doc.nama_orang_tua_wali) {
      frappe.msgprint(__("Nama Orang Tua / Wali wajib diisi."));
      return;
    }

    frappe.confirm(__("Buat Customer dari data orang tua/wali?"), () => {
      frappe.call({
        method: "frappe.client.insert",
        args: {
          doc: {
            doctype: "Customer",
            customer_name: frm.doc.nama_orang_tua_wali,
            customer_type: "Individual",

            // Sesuaikan dengan master ERPNext di site kamu jika berbeda.
            customer_group: "Individual",
            territory: "Indonesia",

            mobile_no: frm.doc.nomor_handphone
          }
        },
        freeze: true,
        freeze_message: __("Membuat Customer..."),
        callback(r) {
          if (!r.exc && r.message) {
            frm.set_value("customer_orang_tua", r.message.name);
            frm.save().then(() => {
              frappe.msgprint({
                title: __("Customer Dibuat"),
                message: __("Customer {0} berhasil dibuat.", [r.message.name]),
                indicator: "green"
              });
            });
          }
        }
      });
    });
  }
});

frappe.ui.form.on("Rumba Pendaftaran", {
  refresh(frm) {
    if (frm.is_new()) {
      return;
    }

    if (frm.doc.sales_invoice) {
      frm.add_custom_button(__("Buka Invoice"), () => {
        frappe.set_route("Form", "Sales Invoice", frm.doc.sales_invoice);
      });
      return;
    }

    if (frm.doc.customer_orang_tua) {
      frm.add_custom_button(__("Buat Invoice"), () => {
        frm.trigger("buat_invoice");
      });
    }
  },

  buat_invoice(frm) {
    const dialog = new frappe.ui.Dialog({
      title: __("Buat Invoice"),
      fields: [
        {
          fieldname: "item_code",
          fieldtype: "Link",
          label: __("Item"),
          options: "Item",
          reqd: 1
        },
        {
          fieldname: "rate",
          fieldtype: "Currency",
          label: __("Nominal"),
          reqd: 1
        },
        {
          fieldname: "due_date",
          fieldtype: "Date",
          label: __("Tanggal Jatuh Tempo"),
          default: frappe.datetime.add_days(frappe.datetime.get_today(), 7),
          reqd: 1
        },
        {
          fieldname: "submit_invoice",
          fieldtype: "Check",
          label: __("Submit Invoice Sekarang"),
          default: 1
        }
      ],
      primary_action_label: __("Buat"),
      primary_action(values) {
        dialog.hide();

        frappe.call({
          method: "rumba16.bimbel_rumba_v16.doctype.rumba_pendaftaran.rumba_pendaftaran.buat_sales_invoice",
          args: {
            pendaftaran: frm.doc.name,
            item_code: values.item_code,
            rate: values.rate,
            due_date: values.due_date,
            submit_invoice: values.submit_invoice ? 1 : 0
          },
          freeze: true,
          freeze_message: __("Membuat invoice..."),
          callback(r) {
            if (!r.exc && r.message) {
              frappe.msgprint({
                title: __("Invoice Dibuat"),
                message: __("Sales Invoice {0} berhasil dibuat.", [r.message]),
                indicator: "green"
              });
              frm.reload_doc();
            }
          }
        });
      }
    });

    dialog.show();
  }
});
